pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a fake token that reverts on transferFrom
        address token = address(new Token());
        address[] memory tos = new address[](1);
        tos[0] = address(0xdead);

        // Reference contract would revert, buggy one returns true
        bool ok;
        try c.transfer(address(0xbeef), token, tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct behavior is a revert (ok == false)
        // Buggy version does not require the call success, so it returns true
        assertTrue(ok == false, "Buggy contract does not revert on failed transferFrom");
    }
}

