pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a helper contract that writes to storage slot 1 in its fallback
        Helper helper = new Helper();
        // Ensure C's storage slot 1 is initially 0
        uint256 slot1;
        assembly {
            slot1 := sload(1)
        }
        assertTrue(slot1 == 0);
        // Call transfer with caddress = helper, which will trigger delegatecall in the buggy version
        address[] memory tos = new address[](1);
        tos[0] = address(0x2);
        c.transfer(address(0x1), address(helper), tos, 1);
        // After the call, check C's storage slot 1: reference uses call, so should remain 0; buggy delegatecall would set it to 1
        uint256 slot1After;
        assembly {
            slot1After := sload(1)
        }
        assertTrue(slot1After == 0);
    }
}

contract Helper {
    fallback() external payable {
        assembly {
            sstore(1, 1)
        }
    }
}
